_v3:"precision mediump float;\n#define LOWPREC lowp\n// Uniforms look like they're shared between vertex and fragment shaders in GLSL, so we have to be careful to avoid name clashes\n\nuniform sampler2D gm_BaseTexture;\n\nuniform bool gm_PS_FogEnabled;\nuniform vec4 gm_FogColour;\nuniform bool gm_AlphaTestEnabled;\nuniform float gm_AlphaRefValue;\n\nvoid DoAlphaTest(vec4 SrcColour)\n{\n	if (gm_AlphaTestEnabled)\n	{\n		if (SrcColour.a <= gm_AlphaRefValue)\n		{\n			discard;\n		}\n	}\n}\n\nvoid DoFog(inout vec4 SrcColour, float fogval)\n{\n	if (gm_PS_FogEnabled)\n	{\n		SrcColour = mix(SrcColour, gm_FogColour, clamp(fogval, 0.0, 1.0)); \n	}\n}\n\n#define _YY_GLSLES_ 1\n// Draws a sprite as a solid silhouette (hit flash, impact frame); keeps the sprite's alpha.\n// White unless u_col is set: rgb = the colour, a = 1 to use it (left unset, every uniform is 0, so it stays white)\nvarying vec2 v_vTexcoord;\nvarying vec4 v_vColour;\n\nuniform vec4 u_col;\n\nvoid main()\n{\n    gl_FragColor = vec4(mix(vec3(1.0), u_col.rgb, u_col.a), texture2D(gm_BaseTexture, v_vTexcoord).a * v_vColour.a);\n}\n",
